css:
/* Fresh India print format - palette from the logo. wkhtmltopdf-safe (no flex/grid). */
.print-format { padding: 0 !important; max-width: none !important; width: 100% !important; }
.letter-head, .letter-head-footer { display: none !important; }
.fis { font-family: "Helvetica Neue", Helvetica, Arial, "DejaVu Sans", sans-serif; font-size: 10.5px; color: #2d3436; position: relative; }
.fis table { width: 100%; border-collapse: collapse; }
.fis td, .fis th { vertical-align: top; }
.fis .r { text-align: right; }
.fis .c { text-align: center; }
.fis .b { font-weight: bold; }
.fis .items tr, .fis .hsn tr, .fis .totals tr { page-break-inside: avoid; }
.fis .items { table-layout: fixed; }
.fis .items td.r, .fis .items td.c, .fis .items th.r { white-space: nowrap; }
.fis .items td.r { font-size: 9px; }
.fis .totals td.r { font-size: 11px; }
.fis .totals td { padding: 6px 8px; }
.fis .items td { font-size: 9.5px; }

/* watermark for draft / cancelled */
.fis .watermark { position: absolute; top: 300px; left: 0; width: 100%; text-align: center; font-size: 110px; font-weight: bold;
  color: rgba(214, 48, 49, 0.10); -webkit-transform: rotate(-28deg); transform: rotate(-28deg); z-index: 0; letter-spacing: 8px; }

/* header */
.fis .hdr td { vertical-align: middle; }
.fis .logo-cell { width: 132px; padding-right: 14px; }
.fis .logo { width: 128px; display: block; }
.fis .co-name { font-size: 22px; font-weight: bold; color: #1f7a33; letter-spacing: .3px; }
.fis .co-addr { color: #555; margin: 3px 0 4px; line-height: 1.35; }
.fis .co-ids { color: #444; font-size: 9.5px; line-height: 1.5; }
.fis .title-cell { width: 200px; text-align: right; }
.fis .doc-title { display: inline-block; white-space: nowrap; background: #F47B20; color: #fff; font-size: 17px; font-weight: bold;
  letter-spacing: 1.5px; padding: 7px 14px; border-radius: 4px; }
.fis .doc-sub { font-size: 9px; color: #888; margin-top: 4px; text-transform: uppercase; letter-spacing: 1px; }
.fis .stamp { display: inline-block; margin-top: 6px; padding: 3px 10px; border: 1.5px solid; border-radius: 12px;
  font-size: 10px; font-weight: bold; text-transform: uppercase; letter-spacing: 1px; }
.fis .stamp.ok { color: #1f7a33; border-color: #2E9B3E; background: #EEF8EF; }
.fis .stamp.bad { color: #c0392b; border-color: #e74c3c; background: #fdecea; }
.fis .stamp.warn { color: #b9600f; border-color: #F47B20; background: #FFF4EA; }
.fis .stamp.muted { color: #636e72; border-color: #b2bec3; background: #f5f6f7; }

/* two-tone brand bar */
.fis .bar { height: 5px; background: #2E9B3E; margin: 8px 0 8px; border-radius: 3px; }
.fis .bar-o { height: 5px; width: 38%; background: #F47B20; border-radius: 3px 0 0 3px; }

/* meta strip */
.fis .meta { background: #FFF4EA; border: 1px solid #fbd9bd; border-radius: 4px; }
.fis .meta td { padding: 7px 10px; border-right: 1px solid #fbd9bd; }
.fis .meta td:last-child { border-right: 0; }
.fis .lbl { display: block; font-size: 8.5px; text-transform: uppercase; letter-spacing: .8px; color: #b9600f; margin-bottom: 2px; }
.fis .val { font-weight: bold; font-size: 11px; color: #2d3436; }

/* parties */
.fis .parties { margin-top: 8px; }
.fis .party { width: 49%; border: 1px solid #cfe9d3; border-radius: 4px; padding: 0 0 8px; }
.fis .gap { width: 2%; }
.fis .party-h { background: #EEF8EF; color: #1f7a33; font-weight: bold; text-transform: uppercase; font-size: 9px;
  letter-spacing: 1px; padding: 5px 10px; border-bottom: 1px solid #cfe9d3; margin-bottom: 6px; }
.fis .party-name { font-weight: bold; font-size: 12.5px; padding: 0 10px; }
.fis .party-addr { color: #555; padding: 2px 10px 4px; line-height: 1.35; }
.fis .party-ids { padding: 1px 10px; font-size: 9.5px; color: #444; }

/* items */
.fis .items { margin-top: 10px; }
.fis .items th { background: #2E9B3E; color: #fff; font-size: 9px; text-transform: uppercase; letter-spacing: .5px;
  padding: 6px 4px; font-weight: bold; }
.fis .items td { padding: 5px 4px; border-bottom: 1px solid #e8ece9; }
.fis .items tbody tr:nth-child(even) td { background: #f7fbf7; }
.fis .items .idx { color: #999; }
.fis .it-name { font-weight: bold; color: #2d3436; }
.fis .it-code { font-size: 8.5px; color: #888; margin-top: 1px; }
.fis .uom { font-size: 8.5px; color: #888; }
.fis .disc { color: #c0392b; }
.fis .items tfoot td { font-weight: bold; background: #EEF8EF; border-top: 2px solid #2E9B3E; border-bottom: 0; padding: 6px 4px; white-space: nowrap; }

/* summary */
.fis .summary { margin-top: 10px; table-layout: fixed; }
.fis .foot { table-layout: fixed; }
.fis .stamp { white-space: nowrap; }
.fis .sum-left { width: 48%; }
.fis .sum-right { width: 50%; }
.fis .words { background: #f7fbf7; border-left: 3px solid #2E9B3E; padding: 6px 10px; font-weight: bold; margin-bottom: 8px; }
.fis .words .lbl { color: #1f7a33; }
.fis .sec-h { color: #1f7a33; font-weight: bold; text-transform: uppercase; font-size: 9px; letter-spacing: 1px; margin: 8px 0 3px; }
.fis .hsn th { background: #f1f3f2; color: #555; font-size: 8.5px; text-transform: uppercase; padding: 4px 6px; border-bottom: 1px solid #dfe4e1; }
.fis .hsn td { padding: 4px 6px; border-bottom: 1px solid #eef1ef; font-size: 9.5px; }
.fis .kv td { padding: 2px 6px; font-size: 9.5px; }
.fis .kv td:first-child { color: #888; width: 32%; }
.fis .totals td { padding: 6px 10px; border-bottom: 1px solid #eef1ef; white-space: nowrap; }
.fis .totals tr.neg td { color: #c0392b; }
.fis .totals tr.grand td { background: #F47B20; color: #fff; font-size: 14px; font-weight: bold; border: 0; padding: 9px 10px; }
.fis .totals tr.due td { background: #fdecea; color: #c0392b; font-weight: bold; font-size: 12px; }
.fis .totals tr.due.zero td { background: #EEF8EF; color: #1f7a33; }

/* yellow highlight for the final order value (Purchase Order + Sales Order) */
.fis .totals tr.net td { background: #fffbe0; color: #2d3436; font-weight: bold; font-size: 12px; border-bottom: 1px solid #f5d84a; }
.fis .totals tr.net td:first-child { border-left: 4px solid #f5c400; }
.fis .totals tr.grand.hl td { background: #ffe14d; color: #1d2b24; font-size: 13px; border-top: 2px solid #f5c400; border-bottom: 2px solid #f5c400; }
.fis .totals tr.grand.hl td:first-child { border-left: 4px solid #e0a800; }
.fis .totals tr.grand.hl td:last-child { border-right: 4px solid #e0a800; }
.fis .words.hl { background: #fffbe0; border-left-color: #f5c400; }
.fis .words.hl .lbl { color: #9a7400; }

/* terms + signature */
.fis .foot { margin-top: 10px; page-break-inside: avoid; border-top: 1px dashed #cfd8d3; }
.fis .terms { width: 60%; padding-top: 6px; }
.fis .terms-body { margin: 0; padding-left: 16px; color: #555; font-size: 9px; line-height: 1.55; }
.fis .sign { width: 40%; text-align: right; padding-top: 10px; }
.fis .sign-box { display: inline-block; width: 44%; text-align: center; font-size: 9.5px; color: #555; margin-left: 3%; vertical-align: bottom; }
.fis .sign-for { font-weight: bold; color: #1f7a33; margin-bottom: 28px; font-size: 10px; }
.fis .sign-line { border-top: 1px solid #555; margin: 36px 0 4px; }
.fis .sign-for + .sign-line { margin-top: 0; }
.fis .thanks { text-align: center; margin-top: 10px; color: #F47B20; font-weight: bold; font-size: 12px; letter-spacing: .5px; }
.fis .gen { color: #aaa; font-size: 8.5px; font-weight: normal; letter-spacing: 0; }

html:
{#- Fresh India Purchase Order print format. Same look as the sales formats; Net Total and Grand Total are highlighted yellow. Tables only (wkhtmltopdf). -#}
{%- set company = frappe.db.get_value("Company", doc.company, ["company_name", "phone_no", "email", "website", "pan"], as_dict=True) or {} -%}

{%- macro money(v) -%}{{ frappe.utils.fmt_money(v or 0, 2, doc.currency) }}{%- endmacro -%}
{%- macro num(v) -%}{{ frappe.utils.fmt_money(v or 0, 2) }}{%- endmacro -%}
{%- macro addr(s) -%}{{ (s or "").replace("<br>", ",").replace("\n", "").split(",") | map("trim") | reject("equalto", "") | join(", ") }}{%- endmacro -%}
{%- macro pct(v) -%}{{ "%g"|format(frappe.utils.flt(v, 2)) }}%{%- endmacro -%}
{%- macro qty(v) -%}{{ frappe.utils.fmt_money(v or 0, 0) if (v or 0) == (v or 0)|round(0) else frappe.utils.fmt_money(v or 0, 2) }}{%- endmacro -%}

{%- set has_igst = (doc.items | sum(attribute="igst_amount")) != 0 -%}
{%- set gst_rates = [] -%}{%- for it in doc.items -%}{%- set _ = gst_rates.append((it.igst_rate or 0) + (it.cgst_rate or 0) + (it.sgst_rate or 0)) -%}{%- endfor -%}
{%- set single_rate = gst_rates[0] if (gst_rates | unique | list | length) == 1 else none -%}
{%- set has_disc = namespace(v=false) -%}
{%- for it in doc.items -%}{%- if it.price_list_rate and it.rate < it.price_list_rate -%}{%- set has_disc.v = true -%}{%- endif -%}{%- endfor -%}

{%- set status = doc.status if doc.docstatus == 1 else ("Draft" if doc.docstatus == 0 else "Cancelled") -%}
{%- set stamp_class = {"Completed": "ok", "Delivered": "ok", "Cancelled": "bad", "Draft": "muted", "Closed": "muted", "On Hold": "bad"}.get(status, "warn") -%}

<div class="fis">
  {%- if doc.docstatus != 1 -%}<div class="watermark">{{ status | upper }}</div>{%- endif -%}

  <!-- ===== Header ===== -->
  <table class="hdr">
    <tr>
      <td class="logo-cell"><img class="logo" src="data:image/png;base64," alt="logo"></td>
      <td class="co">
        <div class="co-name">{{ company.company_name or doc.company }}</div>
        <div class="co-addr">{{ addr(doc.billing_address_display) }}</div>
        <div class="co-ids">
          {%- if doc.company_gstin -%}<b>GSTIN:</b> {{ doc.company_gstin }}{%- endif -%}
          {%- if company.pan -%} &nbsp;|&nbsp; <b>PAN:</b> {{ company.pan }}{%- endif -%}
        </div>
        <div class="co-ids">
          {%- if company.phone_no -%}&#9742; {{ company.phone_no }}{%- endif -%}
          {%- if company.email -%} &nbsp;|&nbsp; &#9993; {{ company.email }}{%- endif -%}
          {%- if company.website -%} &nbsp;|&nbsp; {{ company.website }}{%- endif -%}
        </div>
      </td>
      <td class="title-cell">
        <div class="doc-title">PURCHASE ORDER</div>
        <div class="stamp {{ stamp_class }}">{{ status }}</div>
      </td>
    </tr>
  </table>
  <div class="bar"><div class="bar-o"></div></div>

  <!-- ===== Document meta ===== -->
  <table class="meta">
    <tr>
      <td><span class="lbl">PO No.</span><span class="val">{{ doc.name }}</span></td>
      <td><span class="lbl">PO Date</span><span class="val">{{ frappe.utils.formatdate(doc.transaction_date) }}</span></td>
      <td><span class="lbl">Required By</span><span class="val">{{ frappe.utils.formatdate(doc.schedule_date) }}</span></td>
      <td><span class="lbl">Supplier Ref.</span><span class="val">{{ doc.order_confirmation_no or "-" }}</span></td>
      <td><span class="lbl">Place of Supply</span><span class="val">{{ doc.place_of_supply or "-" }}</span></td>
    </tr>
  </table>

  <!-- ===== Parties ===== -->
  <table class="parties">
    <tr>
      <td class="party">
        <div class="party-h">Supplier</div>
        <div class="party-name">{{ doc.supplier_name }}</div>
        <div class="party-addr">{{ addr(doc.address_display) }}</div>
        <div class="party-ids">
          {%- if doc.supplier_gstin -%}<b>GSTIN:</b> {{ doc.supplier_gstin }}{%- else -%}<b>GST:</b> {{ doc.gst_category or "Unregistered" }}{%- endif -%}
        </div>
        {%- if doc.contact_display -%}
        <div class="party-ids"><b>Contact:</b> {{ doc.contact_display }}{% if doc.contact_mobile %}, {{ doc.contact_mobile }}{% endif %}{% if doc.contact_email %}, {{ doc.contact_email }}{% endif %}</div>
        {%- endif -%}
      </td>
      <td class="gap"></td>
      <td class="party">
        <div class="party-h">Deliver To</div>
        <div class="party-name">{{ company.company_name or doc.company }}{% if doc.set_warehouse %} <small style="font-weight:normal;color:#888">&middot; {{ doc.set_warehouse }}</small>{% endif %}</div>
        <div class="party-addr">{{ addr(doc.shipping_address_display or doc.billing_address_display) }}</div>
        <div class="party-ids">{%- if doc.company_gstin -%}<b>GSTIN:</b> {{ doc.company_gstin }}{%- endif -%}</div>
      </td>
    </tr>
  </table>

  <!-- ===== Items ===== -->
  <table class="items">
    <thead>
      <tr>
        {#- number columns sized for crore values (1,36,29,000.00) -#}
        <th class="c" style="width:3%">#</th>
        <th style="width:{{ '20%' if has_disc.v else '27%' }}">Item &amp; Description</th>
        <th class="c" style="width:8%">HSN/SAC</th>
        <th class="r" style="width:5%">Qty</th>
        <th class="r" style="width:12%">Rate</th>
        {%- if has_disc.v -%}<th class="r" style="width:7%">Disc.</th>{%- endif -%}
        <th class="r" style="width:14%">Taxable</th>
        <th class="c" style="width:5%">GST</th>
        <th class="r" style="width:12%">GST Amt</th>
        <th class="r" style="width:14%">Amount</th>
      </tr>
    </thead>
    <tbody>
      {%- for it in doc.items -%}
      {%- set taxable = it.taxable_value or it.net_amount -%}
      {%- set gst_rate = (it.igst_rate or 0) + (it.cgst_rate or 0) + (it.sgst_rate or 0) -%}
      {%- set gst_amt = (it.igst_amount or 0) + (it.cgst_amount or 0) + (it.sgst_amount or 0) -%}
      {%- set disc = (it.price_list_rate - it.rate) if (it.price_list_rate and it.rate < it.price_list_rate) else 0 -%}
      <tr>
        <td class="c idx">{{ loop.index }}</td>
        <td>
          <div class="it-name">{{ it.item_name }}</div>
          <div class="it-code">{{ it.item_code }}{% if it.schedule_date %} &middot; Req. by {{ frappe.utils.formatdate(it.schedule_date) }}{% endif %}</div>
        </td>
        <td class="c">{{ it.gst_hsn_code or "" }}</td>
        <td class="r">{{ qty(it.qty) }}<div class="uom">{{ it.uom }}</div></td>
        <td class="r">{{ num(it.price_list_rate if disc else it.rate) }}</td>
        {%- if has_disc.v -%}
        <td class="r disc">{% if disc %}{{ pct(disc / it.price_list_rate * 100) }}<div class="it-code">-{{ num(disc) }}</div>{% else %}-{% endif %}</td>
        {%- endif -%}
        <td class="r">{{ num(taxable) }}</td>
        <td class="c">{{ pct(gst_rate) }}</td>
        <td class="r">{{ num(gst_amt) }}</td>
        <td class="r b">{{ num(taxable + gst_amt) }}</td>
      </tr>
      {%- endfor -%}
    </tbody>
    <tfoot>
      <tr>
        <td colspan="3" class="r">Total</td>
        <td class="r">{{ qty(doc.total_qty) }}</td>
        <td></td>
        {%- if has_disc.v -%}<td></td>{%- endif -%}
        <td class="r">{{ num(doc.net_total) }}</td>
        <td></td>
        <td class="r">{{ num(doc.total_taxes_and_charges) }}</td>
        <td class="r">{{ num(doc.net_total + doc.total_taxes_and_charges) }}</td>
      </tr>
    </tfoot>
  </table>

  <!-- ===== Summary ===== -->
  <table class="summary">
    <tr>
      <td class="sum-left">
        <div class="words hl"><span class="lbl">Total order value in words</span>{{ doc.in_words }}</div>

        {%- set hsn = {} -%}
        {%- for it in doc.items -%}
          {%- set k = it.gst_hsn_code or "-" -%}
          {%- if k not in hsn -%}{%- set _ = hsn.update({k: {"taxable": 0, "cgst": 0, "sgst": 0, "igst": 0, "rate": (it.igst_rate or 0) + (it.cgst_rate or 0) + (it.sgst_rate or 0)}}) -%}{%- endif -%}
          {%- set row = hsn[k] -%}
          {%- set _ = row.update({"taxable": row.taxable + (it.taxable_value or it.net_amount), "cgst": row.cgst + (it.cgst_amount or 0), "sgst": row.sgst + (it.sgst_amount or 0), "igst": row.igst + (it.igst_amount or 0)}) -%}
        {%- endfor -%}
        <table class="hsn">
          <thead>
            <tr>
              <th>HSN/SAC</th><th class="r">Taxable</th><th class="c">Rate</th>
              {%- if has_igst -%}<th class="r">IGST</th>{%- else -%}<th class="r">CGST</th><th class="r">SGST</th>{%- endif -%}
              <th class="r">Total Tax</th>
            </tr>
          </thead>
          <tbody>
            {%- for k, r in hsn.items() -%}
            <tr>
              <td>{{ k }}</td><td class="r">{{ num(r.taxable) }}</td><td class="c">{{ pct(r.rate) }}</td>
              {%- if has_igst -%}<td class="r">{{ num(r.igst) }}</td>{%- else -%}<td class="r">{{ num(r.cgst) }}</td><td class="r">{{ num(r.sgst) }}</td>{%- endif -%}
              <td class="r">{{ num(r.cgst + r.sgst + r.igst) }}</td>
            </tr>
            {%- endfor -%}
          </tbody>
        </table>

        {%- if doc.payment_schedule -%}
        <div class="sec-h">Payment Terms{% if doc.payment_terms_template %} &middot; {{ doc.payment_terms_template }}{% endif %}</div>
        <table class="hsn">
          <thead><tr><th>Term</th><th class="c">Due Date</th><th class="c">Portion</th><th class="r">Amount</th></tr></thead>
          <tbody>
            {%- for p in doc.payment_schedule -%}
            <tr><td>{{ p.payment_term or "Payment" }}</td><td class="c">{{ frappe.utils.formatdate(p.due_date) }}</td><td class="c">{{ pct(p.invoice_portion) }}</td><td class="r">{{ num(p.payment_amount) }}</td></tr>
            {%- endfor -%}
          </tbody>
        </table>
        {%- endif -%}
      </td>
      <td class="gap"></td>
      <td class="sum-right">
        <table class="totals">
          <tr><td>Sub Total</td><td class="r">{{ money(doc.total) }}</td></tr>
          {%- if doc.discount_amount -%}
          <tr class="neg"><td>Discount</td><td class="r">- {{ money(doc.discount_amount) }}</td></tr>
          {%- endif -%}
          <tr class="net"><td>Net Total</td><td class="r">{{ money(doc.net_total) }}</td></tr>
          {%- for t in doc.taxes -%}{%- if t.tax_amount -%}
          {%- set head = t.account_head.split(" - ")[0].replace("Input Tax ", "") -%}
          <tr><td>{{ head }}{% if single_rate %} @ {{ pct(single_rate if "IGST" in head else single_rate / 2) }}{% endif %}</td><td class="r">{{ money(t.tax_amount) }}</td></tr>
          {%- endif -%}{%- endfor -%}
          {%- if doc.rounding_adjustment -%}
          <tr><td>Rounding</td><td class="r">{{ money(doc.rounding_adjustment) }}</td></tr>
          {%- endif -%}
          <tr class="grand hl"><td>Total Order Value</td><td class="r">{{ money(doc.rounded_total or doc.grand_total) }}</td></tr>
        </table>
      </td>
    </tr>
  </table>

  <!-- ===== Terms & signatures ===== -->
  <table class="foot">
    <tr>
      <td class="terms">
        <div class="sec-h">Terms &amp; Conditions</div>
        {%- if doc.terms -%}
          <div class="terms-body">{{ (doc.terms or "") | replace("\n", "<br>") }}</div>
        {%- else -%}
          <ol class="terms-body">
            <li>Please quote this PO number on your tax invoice, delivery challan and all correspondence.</li>
            <li>Deliver by the "Required By" date to the address above; partial deliveries only with prior approval.</li>
            <li>Goods are subject to inspection on receipt; rejected material will be returned at the supplier's cost.</li>
            <li>Your GST invoice must show our GSTIN {{ doc.company_gstin or "" }} and HSN codes as per this order.</li>
          </ol>
        {%- endif -%}
      </td>
      <td class="sign">
        <div class="sign-box"><div class="sign-line"></div>Supplier Acceptance</div>
        <div class="sign-box">
          <div class="sign-for">For {{ company.company_name or doc.company }}</div>
          <div class="sign-line"></div>Authorised Signatory
        </div>
      </td>
    </tr>
  </table>

  <div class="thanks">Thank you! <span class="gen">&nbsp;&middot;&nbsp; This is a computer generated purchase order.</span></div>
</div>

